public struct Agent: Equatable, Hashable {
    public let id: String
    public let name: String
    public let role: String
    /**
     * Title of the task the agent is currently assigned, if any.
     */
    public let task: String?
    public let status: AgentStatus
    /**
     * Free-text description of what the agent is doing right now.
     */
    public let activity: String
    public let runtime: RuntimeKind
    public let model: String?
    public let workdir: String
    public let branch: String?
    /**
     * Process backend hosting the agent: `pty` or `herdr`.
     */
    public let backend: String
    /**
     * Backend-specific handle (the herdr pane id).
     */
    public let backendRef: String?
    public let pid: UInt32?
    /**
     * The runtime's own session id (used to resume after a crash).
     */
    public let sessionId: String?
    public let orchestrator: Bool
    /**
     * The agent that launched this one, for dynamically spawned subagents.
     */
    public let parent: String?
    /**
     * Added by the orchestrator once the founding team was settled: it is
     * not saved with the roster, and leaves the team when its work is done.
     */
    public let temporary: Bool
    /**
     * In-session subagents (e.g. Claude Code's Task tool) currently running.
     */
    public let subagents: UInt32
    /**
     * How bus messages reach the session: `socket` (pushed over the daemon's
     * Unix socket into the runtime) or `terminal` (typed into its terminal).
     */
    public let delivery: String
    public let startedAt: Int64?
    public let lastActivityAt: Int64
    public let progress: UInt8?
    public let paused: Bool
    /**
     * Why the agent is blocked: `permission`, `dialog`, `self`,
     * `unresponsive`, `usage_limit`, `refused` (its model declined the
     * turn's content), or `provider_error` (the runtime could not finish the turn).
     */
    public let blockKind: String?
    /**
     * Set while the agent waits for a usage limit to lift.
     */
    public let limit: UsageLimit?
    /**
     * How full the session's context window is, when the runtime says.
     */
    public let context: ContextUsage?
    /**
     * A compaction of the session was asked for and has not happened yet.
     */
    public let compactPending: Bool
    /**
     * How often the session's context has been compacted.
     */
    public let compactions: UInt32
    /**
     * The model the session says it runs on (the runtime's own id for it).
     */
    public let runningModel: String?
    /**
     * The model's proper name, for display: `Opus 5.5`, `GPT 6 Astra`.
     */
    public let modelName: String?
    /**
     * The reasoning effort the session runs at (`low` … `max`), when the
     * runtime says.
     */
    public let effort: String?
    /**
     * Set while the session runs on a model other than the one the member
     * was given.
     */
    public let fallback: ModelFallback?
    public let exitCode: Int32?
    public let restarts: UInt32
    public let inboxUnread: UInt32
    public let inboxTotal: UInt32
    public let outboxTotal: UInt32
    public let usage: Usage?
    public let error: String?

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(id: String, name: String, role: String, 
        /**
         * Title of the task the agent is currently assigned, if any.
         */task: String?, status: AgentStatus, 
        /**
         * Free-text description of what the agent is doing right now.
         */activity: String, runtime: RuntimeKind, model: String?, workdir: String, branch: String?, 
        /**
         * Process backend hosting the agent: `pty` or `herdr`.
         */backend: String, 
        /**
         * Backend-specific handle (the herdr pane id).
         */backendRef: String?, pid: UInt32?, 
        /**
         * The runtime's own session id (used to resume after a crash).
         */sessionId: String?, orchestrator: Bool, 
        /**
         * The agent that launched this one, for dynamically spawned subagents.
         */parent: String?, 
        /**
         * Added by the orchestrator once the founding team was settled: it is
         * not saved with the roster, and leaves the team when its work is done.
         */temporary: Bool, 
        /**
         * In-session subagents (e.g. Claude Code's Task tool) currently running.
         */subagents: UInt32, 
        /**
         * How bus messages reach the session: `socket` (pushed over the daemon's
         * Unix socket into the runtime) or `terminal` (typed into its terminal).
         */delivery: String, startedAt: Int64?, lastActivityAt: Int64, progress: UInt8?, paused: Bool, 
        /**
         * Why the agent is blocked: `permission`, `dialog`, `self`,
         * `unresponsive`, `usage_limit`, `refused` (its model declined the
         * turn's content), or `provider_error` (the runtime could not finish the turn).
         */blockKind: String?, 
        /**
         * Set while the agent waits for a usage limit to lift.
         */limit: UsageLimit?, 
        /**
         * How full the session's context window is, when the runtime says.
         */context: ContextUsage?, 
        /**
         * A compaction of the session was asked for and has not happened yet.
         */compactPending: Bool, 
        /**
         * How often the session's context has been compacted.
         */compactions: UInt32, 
        /**
         * The model the session says it runs on (the runtime's own id for it).
         */runningModel: String?, 
        /**
         * The model's proper name, for display: `Opus 5.5`, `GPT 6 Astra`.
         */modelName: String?, 
        /**
         * The reasoning effort the session runs at (`low` … `max`), when the
         * runtime says.
         */effort: String?, 
        /**
         * Set while the session runs on a model other than the one the member
         * was given.
         */fallback: ModelFallback?, exitCode: Int32?, restarts: UInt32, inboxUnread: UInt32, inboxTotal: UInt32, outboxTotal: UInt32, usage: Usage?, error: String?) {
        self.id = id
        self.name = name
        self.role = role
        self.task = task
        self.status = status
        self.activity = activity
        self.runtime = runtime
        self.model = model
        self.workdir = workdir
        self.branch = branch
        self.backend = backend
        self.backendRef = backendRef
        self.pid = pid
        self.sessionId = sessionId
        self.orchestrator = orchestrator
        self.parent = parent
        self.temporary = temporary
        self.subagents = subagents
        self.delivery = delivery
        self.startedAt = startedAt
        self.lastActivityAt = lastActivityAt
        self.progress = progress
        self.paused = paused
        self.blockKind = blockKind
        self.limit = limit
        self.context = context
        self.compactPending = compactPending
        self.compactions = compactions
        self.runningModel = runningModel
        self.modelName = modelName
        self.effort = effort
        self.fallback = fallback
        self.exitCode = exitCode
        self.restarts = restarts
        self.inboxUnread = inboxUnread
        self.inboxTotal = inboxTotal
        self.outboxTotal = outboxTotal
        self.usage = usage
        self.error = error
    }

    

    
}

